"""Count-Min Sketch: a probabilistic frequency table with sub-linear space."""

import hashlib
import math


class CountMinSketch:
    """Count-Min Sketch data structure.

    Uses d hash functions (depth) each mapping to w counters (width).
    Space: O(w * d). Estimates are always >= true frequency (one-sided error).
    """

    def __init__(self, width: int, depth: int):
        """Initialize with the given width (counters per row) and depth (number of hash functions).

        Args:
            width: Number of counters per hash function. Higher = more accurate.
            depth: Number of hash functions. Higher = lower probability of over-count.
        """
        if width < 1:
            raise ValueError("width must be >= 1")
        if depth < 1:
            raise ValueError("depth must be >= 1")
        self.width = width
        self.depth = depth
        self.table = [[0] * width for _ in range(depth)]
        self.total_count = 0

    # ---- hashing ----

    def _hash(self, item, seed: int) -> int:
        """Return a bucket index in [0, width) for the given item and seed."""
        h = hashlib.md5(f"{seed}:{item}".encode()).hexdigest()
        return int(h, 16) % self.width

    # ---- core operations ----

    def add(self, item, count: int = 1):
        """Increment the frequency estimate for *item* by *count*."""
        if count < 0:
            raise ValueError("count must be non-negative")
        for i in range(self.depth):
            self.table[i][self._hash(item, i)] += count
        self.total_count += count

    def estimate(self, item) -> int:
        """Return the estimated frequency for *item* (always >= true frequency)."""
        return min(self.table[i][self._hash(item, i)] for i in range(self.depth))

    # ---- convenience dunder methods ----

    def __contains__(self, item) -> bool:
        return self.estimate(item) > 0

    def __len__(self) -> int:
        return self.total_count

    def __repr__(self) -> str:
        return f"CountMinSketch(width={self.width}, depth={self.depth}, total={self.total_count})"

    # ---- merge ----

    def merge(self, other: "CountMinSketch"):
        """Merge *other* into this sketch. Both must have identical dimensions."""
        if self.width != other.width or self.depth != other.depth:
            raise ValueError("cannot merge sketches with different dimensions")
        for i in range(self.depth):
            for j in range(self.width):
                self.table[i][j] += other.table[i][j]
        self.total_count += other.total_count


# ---- helpers ----

def estimate_width(epsilon: float) -> int:
    """Return the width needed for an error bound of *epsilon* (as a fraction)."""
    return math.ceil(math.e / epsilon)


def estimate_depth(delta: float) -> int:
    """Return the depth needed for a failure probability of *delta*."""
    return math.ceil(math.log(1 / delta))


if __name__ == "__main__":
    # quick demo
    cms = CountMinSketch(width=1000, depth=5)
    for word in "the cat sat on the mat the cat".split():
        cms.add(word)
    print(cms)
    for word in ["the", "cat", "sat", "dog"]:
        print(f"  {word!r:6s} => estimated {cms.estimate(word)}")

